     */
    public static ST_Box combineBoundary(ST_Box parentBoundary, ST_Box childBoundary) {
        if (parentBoundary == null) {
            return childBoundary;
        }
        if (childBoundary == null) {
            return parentBoundary;
        }
        return new ST_Box(
