     */
    public String[] expectStrArr(int expectCount) {
        String[] res = new String[expectCount];
        for (int i = 0; i < expectCount; i++) {
            if (i < array.size()) {
                res[i] = (array.get(i));
            } else {
                res[i] = "";
            }
        }
        return res;
    }

    /**
     * 获取浮点数组
     *
     * @return 浮点数组
     */
    public Double[] toDouble() {
        return this.array.stream()
