import org.ujmp.core.Matrix;

import java.text.ParseException;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.*;

class CommonUtilTest {

    private static final double EPS = 1e-6;

    @Test
    void millimeterPixelConversionsRoundTripAtTwentyFivePointFourMillimeters() {
        assertEquals(300.0, CommonUtil.millimetersToPixel(25.4, 300), 1e-4);
        assertEquals(25.4, CommonUtil.pixelToMillimeters(300.0, 300), 1e-4);
        assertEquals(0.0, CommonUtil.millimetersToPixel(0.0, 300), EPS);
        assertEquals(-72.0, CommonUtil.converterDpi(-25.4), 1e-4);
    }

    @Test
    void dpiToPpmUsesOneHundredthMillimeterUnits() {
        assertEquals(10.0, CommonUtil.dpiToPpm(254), 1e-9);
        assertEquals(0.0, CommonUtil.dpiToPpm(0), EPS);
        assertEquals(11.811023622047244, CommonUtil.dpiToPpm(300), 1e-9);
    }

    @Test
    void converterDpiMapsMillimetersToPdfPoints() {
        assertEquals(72.0, CommonUtil.converterDpi(25.4), 1e-4);
        assertEquals(0.0, CommonUtil.converterDpi(0.0), EPS);
    }

    @Test
    void doubleArrayToFloatArrayReturnsEmptyArrayForNull() {
        assertArrayEquals(new float[0], CommonUtil.doubleArrayToFloatArray(null), 0f);
    }

    @Test
    void doubleArrayToFloatArrayConvertsEveryElementInOrder() {
        float[] result = CommonUtil.doubleArrayToFloatArray(new Double[]{1.5d, -2.25d, 0d});
        assertArrayEquals(new float[]{1.5f, -2.25f, 0f}, result, 0f);
        assertArrayEquals(new float[0], CommonUtil.doubleArrayToFloatArray(new Double[0]), 0f);
    }

    @Test
    void getPageBoxPrefersPhysicalThenApplicationThenContentBox() {
        ST_Box physical = new ST_Box(1, 2, 30, 40);
        ST_Box application = new ST_Box(3, 4, 50, 60);
        ST_Box content = new ST_Box(5, 6, 70, 80);

        CT_PageArea all = new CT_PageArea();
        all.setContentBox(content);
        all.setApplicationBox(application);
        all.setPhysicalBox(physical);
        assertBoxEquals(physical, CommonUtil.getPageBox(all, 100, 200));

        CT_PageArea applicationAndContent = new CT_PageArea();
        applicationAndContent.setContentBox(content);
        applicationAndContent.setApplicationBox(application);
        assertBoxEquals(application, CommonUtil.getPageBox(applicationAndContent, 100, 200));

        CT_PageArea contentOnly = new CT_PageArea();
        contentOnly.setContentBox(content);
        assertBoxEquals(content, CommonUtil.getPageBox(contentOnly, 100, 200));
    }

    @Test
    void getPageBoxReturnsNullWhenPageAreaHasNoBox() {
        assertNull(CommonUtil.getPageBox(new CT_PageArea(), 100, 200));
    }

    @Test
    void getPageBoxFallsBackToRequestedSizeForNullPageArea() {
        ST_Box box = CommonUtil.getPageBox(null, 210, 297);
        assertNotNull(box);
        assertBoxEquals(new ST_Box(0, 0, 210, 297), box);
    }

    @Test
    void generateTempFilePathCreatesDistinctUuidNamedPathsUnderTempDirectory() {
        String first = CommonUtil.generateTempFilePath();
        String second = CommonUtil.generateTempFilePath();

        String prefix = System.getProperty("java.io.tmpdir") + "/";
        assertTrue(first.startsWith(prefix), "path should be under java.io.tmpdir");
        assertTrue(second.startsWith(prefix), "path should be under java.io.tmpdir");
        assertNotEquals(first, second);
        assertDoesNotThrow(() -> UUID.fromString(first.substring(prefix.length())));
    }

    @Test
    void convertPDColorConvertsNumericRgbAndGrayArrays() {
        PDColor rgb = CommonUtil.convertPDColor(new ST_Array("255", "128", "0"));
        assertNotNull(rgb);
        assertSame(PDDeviceRGB.INSTANCE, rgb.getColorSpace());
        assertArrayEquals(new float[]{1.0f, 128f / 255f, 0f}, rgb.getComponents(), 1e-6f);

        PDColor gray = CommonUtil.convertPDColor(new ST_Array("128"));
        assertNotNull(gray);
        assertSame(PDDeviceGray.INSTANCE, gray.getColorSpace());
        assertArrayEquals(new float[]{128f / 255f}, gray.getComponents(), 1e-6f);
    }

    @Test
    void convertPDColorSupportsHexColorTriplets() {
        PDColor color = CommonUtil.convertPDColor(new ST_Array("#FF", "00", "80"));
        assertNotNull(color);
        assertSame(PDDeviceRGB.INSTANCE, color.getColorSpace());
        assertArrayEquals(new float[]{1.0f, 0f, 128f / 255f}, color.getComponents(), 1e-6f);
    }

    @Test
    void convertPDColorReturnsNullForUnsupportedComponentCount() {
        assertNull(CommonUtil.convertPDColor(new ST_Array("1", "2")));
        assertNull(CommonUtil.convertPDColor(new ST_Array("#FF")));
    }

    @Test
    void convertOfdColorToHtmlRendersHexAndRgbNotation() {
        assertEquals("#FF0080", CommonUtil.convertOfdColorToHtml(new ST_Array("#FF", "00", "80")));
        assertEquals("rgb(255,128,0)", CommonUtil.convertOfdColorToHtml(new ST_Array("255", "128", "0")));
        assertEquals("rgb(128,128,128)", CommonUtil.convertOfdColorToHtml(new ST_Array("128")));
        assertNull(CommonUtil.convertOfdColorToHtml(new ST_Array("1", "2")));
    }

    @Test
    void matrixFromFormatsSixValuesAndConvertsTranslationToDpiUnits() {
        String value = CommonUtil.matrixFrom(new ST_Array("1", "0", "0", "1", "25.4", "0"));
        assertTrue(value.startsWith("matrix("));
        assertTrue(value.endsWith(")"));
        String[] parts = value.substring("matrix(".length(), value.length() - 1).trim().split("\\s+");
        assertEquals(6, parts.length);
        assertEquals(1.0, Double.parseDouble(parts[0]), EPS);
        assertEquals(0.0, Double.parseDouble(parts[1]), EPS);
        assertEquals(0.0, Double.parseDouble(parts[2]), EPS);
        assertEquals(1.0, Double.parseDouble(parts[3]), EPS);
        assertEquals(CommonUtil.converterDpi(25.4), Double.parseDouble(parts[4]), 1e-4);
        assertEquals(0.0, Double.parseDouble(parts[5]), EPS);
    }

    @Test
    void convertV1SignTimeHandlesUtcTimestampVariants() throws ParseException {
        assertEquals(1597149045000L, CommonUtil.convertV1SignTime("2020-08-11T12:30:45Z"));
